CREATE TABLE IF NOT EXISTS users (id VARCHAR(32) PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, role VARCHAR(20) NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS login_tokens (token_hash VARCHAR(64) PRIMARY KEY, user_id VARCHAR(32) NOT NULL, expires BIGINT NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS staff_sessions (token_hash VARCHAR(64) PRIMARY KEY, user_id VARCHAR(32) NOT NULL, expires BIGINT NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS rate_events (id VARCHAR(32) PRIMARY KEY, bucket VARCHAR(64) NOT NULL, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS batches (id VARCHAR(32) PRIMARY KEY, request_key VARCHAR(64) NOT NULL UNIQUE, contact TEXT NOT NULL, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS projects (id VARCHAR(32) PRIMARY KEY, batch_id VARCHAR(32) NOT NULL, payload TEXT NOT NULL, stage VARCHAR(40) NOT NULL, version INTEGER NOT NULL DEFAULT 1, created BIGINT NOT NULL, FOREIGN KEY (batch_id) REFERENCES batches(id));
CREATE TABLE IF NOT EXISTS documents (id VARCHAR(32) PRIMARY KEY, batch_id VARCHAR(32) NOT NULL, original_name VARCHAR(255) NOT NULL, stored_name VARCHAR(64) NOT NULL, bytes BIGINT NOT NULL, mime VARCHAR(100) NOT NULL, FOREIGN KEY (batch_id) REFERENCES batches(id));
CREATE TABLE IF NOT EXISTS events (id VARCHAR(32) PRIMARY KEY, project_id VARCHAR(32) NOT NULL, actor VARCHAR(254) NOT NULL, kind VARCHAR(40) NOT NULL, payload TEXT NOT NULL, created BIGINT NOT NULL, FOREIGN KEY (project_id) REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS outbox (id VARCHAR(32) PRIMARY KEY, recipient VARCHAR(254) NOT NULL, subject VARCHAR(200) NOT NULL, body TEXT NOT NULL, attempts INTEGER NOT NULL, next_attempt BIGINT NOT NULL, sent BIGINT NULL);
